_CORE_SRC = '# Action format: {"moves": [(from_node, to_node, count), ...], "build": n_buy}\n# Payout: equal fleets serve capacity_p * demand / max(capacity_0 + capacity_1,\n# demand); otherwise the bigger fleet serves min(capacity_more, demand), and the\n# smaller serves min(capacity_fewer, demand - served_more).\n# Costs: upkeep_p = 2.0 * (owned drones - drones on own base);\n# profit_p = revenue_p - upkeep_p - 15.0 * drones bought.\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\n\ndef payout(a, b, demand):\n    if demand <= 0:\n        return 0.0, 0.0\n    if a == b:\n        x = 4.0 * a * demand / max(8.0 * a, demand)\n        return x, x\n    if a > b:\n        x = min(4.0 * a, demand)\n        return x, min(4.0 * b, demand - x)\n    y = min(4.0 * b, demand)\n    return min(4.0 * a, demand - y), y\n\n\ndef preprocess(n, edges):\n    adj = [[] for _ in range(n)]\n    for u, v in edges:\n        adj[u].append(v)\n        adj[v].append(u)\n    for row in adj:\n        row.sort()\n    distances = []\n    for s in range(n):\n        d = [n + 1] * n\n        d[s] = 0\n        q = deque([s])\n        while q:\n            u = q.popleft()\n            for v in adj[u]:\n                if d[v] > d[u] + 1:\n                    d[v] = d[u] + 1\n                    q.append(v)\n        distances.append(d)\n    hops = [[s] * n for s in range(n)]\n    for s in range(n):\n        for t in range(n):\n            if s != t:\n                hops[s][t] = min(\n                    v for v in adj[s]\n                    if distances[v][t] == distances[s][t] - 1\n                )\n    return adj, distances, hops\n\n\ndef legal_action(have, target, adj, dist, hops, money=0.0, buy=0):\n    available = list(have)\n    surplus = [max(0, have[i] - target[i]) for i in range(len(have))]\n    deficit = [max(0, target[i] - have[i]) for i in range(len(have))]\n    pairs = sorted((dist[s][t], s, t)\n                   for s in range(len(have)) if surplus[s]\n                   for t in range(len(have)) if deficit[t])\n    moves = {}\n    for _, s, t in pairs:\n        count = min(surplus[s], deficit[t])\n        if count:\n            v = hops[s][t]\n            surplus[s] -= count\n            deficit[t] -= count\n            moves[s, v] = moves.get((s, v), 0) + count\n    result = []\n    for (s, v), count in sorted(moves.items()):\n        count = min(count, available[s])\n        if count > 0 and v in adj[s]:\n            available[s] -= count\n            result.append((int(s), int(v), int(count)))\n    buy = max(0, min(int(buy), 40 - sum(have)))\n    if 15.0 * buy > money:\n        buy = max(0, min(buy, int(max(0.0, money) / 15.0)))\n    return {"moves": result, "build": int(buy)}\n\n\ndef simulate(state, action, opponent_action, demand, bases, adj):\n    """Pure exact one-turn transition; state is (mine, theirs, money, money)."""\n    positions = [list(state[0]), list(state[1])]\n    money = [state[2], state[3]]\n    bought = [0, 0]\n    for p, act in enumerate((action, opponent_action)):\n        available = list(positions[p])\n        for s, t, k in act["moves"]:\n            if (0 <= s < len(adj) and 0 <= t < len(adj)\n                    and t in adj[s] and 0 <= k <= available[s]):\n                available[s] -= k\n                positions[p][s] -= k\n                positions[p][t] += k\n        b = act["build"]\n        if 0 <= b and sum(positions[p]) + b <= 40 and 15.0 * b <= money[p]:\n            positions[p][bases[p]] += b\n            bought[p] = b\n    gain = [-15.0 * bought[0], -15.0 * bought[1]]\n    for i, d in enumerate(demand):\n        x, y = payout(positions[0][i], positions[1][i], d)\n        gain[0] += x - (2.0 * positions[0][i] if i != bases[0] else 0.0)\n        gain[1] += y - (2.0 * positions[1][i] if i != bases[1] else 0.0)\n    return (positions[0], positions[1], money[0] + gain[0],\n            money[1] + gain[1]), gain[0], gain[1]\n\n\ndef value_tables(means, enemy, base, total, denial):\n    tables = []\n    for i, mean in enumerate(means):\n        row = []\n        for k in range(total + 1):\n            if i == base:\n                row.append(0.0)\n                continue\n            value = 0.0\n            for factor in (0.6, 0.8, 1.0, 1.2, 1.4):\n                a, b = payout(k, enemy[i], mean * factor)\n                value += (a - denial * b) / 5.0\n            row.append(value - 2.0 * k)\n        tables.append(row)\n    return tables\n\n\ndef allocate(have, enemy, means, base, dist, horizon, denial):\n    """Bundle allocation handles the discontinuous majority-first payout."""\n    n = len(have)\n    total = sum(have)\n    tables = value_tables(means, enemy, base, total, denial)\n    target = [0] * n\n    target[base] = total\n    supply = list(have)\n    # Greedy bundles include the jump from losing a contest to winning it.\n    for _ in range(total):\n        best = 0.02\n        choice = None\n        for v in range(n):\n            if v == base:\n                continue\n            old = target[v]\n            limit = min(target[base], max(4, enemy[v] + 1) - old)\n            if limit <= 0:\n                continue\n            sources = sorted((dist[s][v], s) for s in range(n) if supply[s])\n            travel = 0.0\n            used = 0\n            for distance, s in sources:\n                for _ in range(min(supply[s], limit - used)):\n                    used += 1\n                    travel += max(0, distance - 1) * 2.5 / horizon\n                    gain = (tables[v][old + used] - tables[v][old] - travel) / used\n                    if gain > best:\n                        best = gain\n                        choice = (v, used)\n                if used >= limit:\n                    break\n        if choice is None:\n            break\n        v, count = choice\n        target[v] += count\n        target[base] -= count\n        left = count\n        for _, s in sorted((dist[s][v], s) for s in range(n) if supply[s]):\n            take = min(left, supply[s])\n            supply[s] -= take\n            left -= take\n            if not left:\n                break\n    return target\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.samples = []\n        self.lower = []\n        self.upper = []\n        self.last_seen = []\n        self.seen_turn = []\n        self.previous = None\n        self.last_turn = -1\n        self.bad = 0\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + 0.58 * TIME_BUDGET\n        n = int(obs["n_nodes"])\n        if self.map_data is None:\n            self.map_data = preprocess(n, obs["edges"])\n            self.samples = [[] for _ in range(n)]\n            self.lower = [1.0] * n\n            self.upper = [10.0] * n\n            self.last_seen = [0] * n\n            self.seen_turn = [-100] * n\n        adj, dist, hops = self.map_data\n        turn = int(obs["turn"])\n        base = int(obs["player_base"])\n        other_base = int(obs["opponent_base"])\n        have = list(obs["player_drones"])\n        demand = list(obs["demand"])\n        visible = obs["opponent_drones"]\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0)):\n            self.bad += 1\n        for i in range(n):\n            if turn != self.last_turn:\n                self.samples[i].append(demand[i])\n                self.lower[i] = max(self.lower[i], (demand[i] - 0.05) / 1.5)\n                self.upper[i] = min(self.upper[i], (demand[i] + 0.05) / 0.5)\n            if visible[i] is not None:\n                self.last_seen[i] = int(visible[i])\n                self.seen_turn[i] = turn\n        self.last_turn = turn\n        means = []\n        for i in range(n):\n            avg = sum(self.samples[i]) / max(1, len(self.samples[i]))\n            means.append(max(self.lower[i], min(self.upper[i], avg)))\n        means[base] = means[other_base] = 0.0\n        enemy = [int(visible[i]) if visible[i] is not None else\n                 (self.last_seen[i] if turn - self.seen_turn[i] < 5 else 0)\n                 for i in range(n)]\n        if turn == 0:\n            enemy[other_base] = 10\n        remaining = 120 - turn\n        horizon = min(16.0, max(1.0, remaining / 3.0))\n        target = allocate(have, enemy, means, base, dist, horizon, 0.8)\n        best_action = legal_action(have, target, adj, dist, hops)\n        best_target = target\n        if self.bad >= 2:\n            return best_action\n\n        candidates = [target, list(have)]\n        if self.previous is not None and sum(self.previous) == sum(have):\n            candidates.append(list(self.previous))\n        for aggression, h in ((0.0, horizon), (1.5, horizon),\n                              (0.8, 5.0), (1.0, 28.0)):\n            if time.perf_counter() >= deadline:\n                break\n            candidates.append(allocate(have, enemy, means, base, dist,\n                                       min(h, max(1, remaining)), aggression))\n        models = [list(enemy)]\n        if time.perf_counter() < deadline:\n            models.append(allocate(enemy, have, means, other_base, dist,\n                                   horizon, 0.8))\n            models.append(allocate(enemy, [0] * n, means, other_base, dist,\n                                   horizon, 0.0))\n        depth = min(6, remaining)\n        best_score = -float("inf")\n        for plan in candidates:\n            if time.perf_counter() >= deadline:\n                break\n            scores = []\n            complete = True\n            for opponent_target in models:\n                if time.perf_counter() >= deadline:\n                    complete = False\n                    break\n                state = (list(have), list(enemy), float(obs["player_money"]), 0.0)\n                score = 0.0\n                last_margin = 0.0\n                for step in range(depth):\n                    a = legal_action(state[0], plan, adj, dist, hops)\n                    b = legal_action(state[1], opponent_target, adj, dist, hops)\n                    values = demand if step == 0 else means\n                    state, x, y = simulate(state, a, b, values,\n                                           (base, other_base), adj)\n                    last_margin = x - y\n                    score += last_margin\n                score += min(5, remaining - depth) * last_margin\n                scores.append(score)\n            if complete and scores:\n                quality = 0.8 * sum(scores) / len(scores) + 0.2 * min(scores)\n                if quality > best_score + 0.05:\n                    best_score = quality\n                    best_target = plan\n                    best_action = legal_action(have, plan, adj, dist, hops)\n\n        # Purchase only when no idle reserve remains and a new drone has a\n        # substantial productive destination, with enough time to repay its cost.\n        buy = 0\n        if (remaining > 35 and sum(have) < 26 and have[base] == 0\n                and obs["player_money"] >= 15.0\n                and time.perf_counter() < deadline):\n            augmented = list(have)\n            augmented[base] += 1\n            expanded = allocate(augmented, enemy, means, base, dist, horizon, 0.5)\n            tables = value_tables(means, enemy, base, sum(augmented), 0.5)\n            improvement = sum(tables[i][expanded[i]] - tables[i][best_target[i]]\n                              for i in range(n))\n            if expanded[base] == 0 and improvement > 0.8:\n                buy = 1\n        self.previous = list(best_target)\n        if buy:\n            self.previous[base] += buy\n        # Rebuild and validate against start-of-turn availability, including\n        # purchase affordability and the absolute fleet limit.\n        return legal_action(have, best_target, adj, dist, hops,\n                            float(obs["player_money"]), buy)\n'
_CORE_CLASS = 'Strategy'
_FALLBACK_SRC = None
_FALLBACK_CLASS = 'Strategy'
_ACT_LIMIT_S = 0.7
_CORE_SHARE = 0.75
_TIME_BUDGET = 0.25
_IMPORT_LIMIT_S = 4.5
_FALLBACK_IMPORT_LIMIT_S = 1.5
_CORE_INIT_LIMIT_S = 2.5
_FALLBACK_INIT_LIMIT_S = 1.5
_MAX_REPLY_CHARS = 900000

_MIN_FALLBACK_S = 0.05
_REPEAT_S = 0.05  # after the first alarm, re-fire every 50 ms until the call returns
_STATE = {"armed": False}
_GUARD_CODES = set()


class _GuardTimeout(BaseException):
    """Raised by the guard's timer. A BaseException: `except Exception` cannot swallow it."""


class _Sink:
    """Swallows output: strategy code must not flood the worker's stderr."""

    encoding = "utf-8"
    errors = "replace"

    def write(self, s):
        return len(s)

    def writelines(self, lines):
        return None

    def flush(self):
        return None

    def isatty(self):
        return False


_SINK = _Sink()


def _noop_print(*args, **kwargs):
    return None


def _on_alarm(signum, frame):
    if _STATE["armed"] and (frame is None or frame.f_code not in _GUARD_CODES):
        raise _GuardTimeout()


def _can_time():
    return (
        hasattr(_signal, "setitimer")
        and hasattr(_signal, "SIGALRM")
        and _threading.current_thread() is _threading.main_thread()
    )


def _plain(value):
    """(True, plain copy) if value is a literal within the reply limit, else (False, None)."""
    try:
        text = repr(value)
        if len(text) > _MAX_REPLY_CHARS:
            return False, None
        if not text.isascii() and len(text.encode("utf-8", "replace")) > _MAX_REPLY_CHARS:
            return False, None  # arena's reply limit counts bytes
        copy = _ast.literal_eval(text)
        if not bool(copy == value):  # NaN, or a type whose repr is not its value
            return False, None
        return True, copy
    except Exception:
        return False, None


def _call(fn, args, limit, check):
    """fn(*args) under a hard timer: (status, value, error, secs). Never raises.

    status: 'ok', 'timeout', 'exception' or 'bad' (check=True and not a plain literal).
    """
    status = "exception"
    value = None
    error = None
    timed = False
    prev_handler = None
    prev_timer = (0.0, 0.0)
    out, err, inp = _sys.stdout, _sys.stderr, _sys.stdin
    t0 = _time.perf_counter()
    try:
        if limit > 0 and _can_time():
            prev_handler = _signal.signal(_signal.SIGALRM, _on_alarm)
            prev_timer = _signal.setitimer(_signal.ITIMER_REAL, limit, _REPEAT_S)
            timed = True
        _sys.stdout = _sys.stderr = _SINK
        _sys.stdin = None  # arena's protocol pipe: untrusted code must not read it
        _STATE["armed"] = timed
        try:
            result = fn(*args)
            if check:
                ok, result = _plain(result)
                status = "ok" if ok else "bad"
            else:
                status = "ok"
            value = result
        except _GuardTimeout as e:
            status = "timeout"
            error = e
        except BaseException as e:
            status = "exception"
            error = e
    except BaseException as e:
        if status == "exception" and error is None:
            error = e
    finally:
        _STATE["armed"] = False
        if timed:
            try:
                _signal.setitimer(_signal.ITIMER_REAL, 0.0)
                _signal.signal(
                    _signal.SIGALRM, prev_handler if prev_handler is not None else _signal.SIG_DFL
                )
                if prev_timer[0] > 0:
                    spent = _time.perf_counter() - t0
                    _signal.setitimer(
                        _signal.ITIMER_REAL, max(prev_timer[0] - spent, 1e-4), prev_timer[1]
                    )
            except BaseException:
                pass
        _sys.stdout, _sys.stderr, _sys.stdin = out, err, inp
    if isinstance(error, _GuardTimeout):
        status = "timeout"
    return status, value, error, _time.perf_counter() - t0


_GUARD_CODES.add(_call.__code__)  # exempt already while the embedded sources load


def _act_of(strategy, obs):
    """strategy.act(obs): inside the timed call, so a missing or broken `act` is caught too."""
    return strategy.act(obs)


def _describe(status, error, secs, limit):
    if status == "timeout":
        where = ""
        try:
            if error is not None:
                frames = _traceback.extract_tb(error.__traceback__)
                frames = [f for f in frames if f.name not in ("_on_alarm", "_call")][-3:]
                where = "\ninterrupted at:\n" + "".join(_traceback.format_list(frames))
        except BaseException:
            where = ""
        return "timeout: no result within %.2f s (limit %.2f s)%s" % (secs, limit, where[-1500:])
    if status == "bad":
        return "bad output: not a plain Python literal within the reply limit"
    try:
        return "".join(_traceback.format_exception(error))[-4000:]
    except BaseException:
        return "exception (traceback unavailable)"


def _load(src, cls_name, label):
    n = 0
    while "_hz_%s_%d" % (label, n) in _sys.modules:
        n += 1
    name = "_hz_%s_%d" % (label, n)
    filename = "<%s>" % name
    _linecache.cache[filename] = (len(src), None, src.splitlines(True), filename)
    module = _types.ModuleType(name)
    module.__file__ = filename
    module.TIME_BUDGET = _TIME_BUDGET
    module.print = _noop_print
    _sys.modules[name] = module
    try:
        exec(compile(src, filename, "exec"), module.__dict__)
        module.TIME_BUDGET = _TIME_BUDGET
        module.print = _noop_print
        return getattr(module, cls_name)
    except BaseException:
        _sys.modules.pop(name, None)
        raise


_LOAD_ERRORS = {}


def _load_all():
    t0 = _time.perf_counter()
    loaded = {"core": None, "fallback": None}
    parts = (
        ("fallback", _FALLBACK_SRC, _FALLBACK_CLASS, _FALLBACK_IMPORT_LIMIT_S),
        ("core", _CORE_SRC, _CORE_CLASS, None),
    )
    for label, src, cls_name, limit in parts:
        if src is None:
            continue
        left = _IMPORT_LIMIT_S - (_time.perf_counter() - t0)
        limit = min(limit, left) if limit is not None else left
        limit = max(limit, 0.5)
        status, value, error, secs = _call(_load, (src, cls_name, label), limit, False)
        if status == "ok":
            loaded[label] = value
        else:
            _LOAD_ERRORS[label] = _describe(status, error, secs, limit)
    return loaded["core"], loaded["fallback"]


try:
    _CORE_CLS, _FALLBACK_CLS = _load_all()
except BaseException:
    _CORE_CLS, _FALLBACK_CLS = None, None


class _HzGuard:
    def __init__(self, player_id):
        self.player_id = player_id
        self._core = None
        self._fallback = None
        self._stats = {
            "turns": 0,
            "core_ok": 0,
            "core_exceptions": 0,
            "core_timeouts": 0,
            "core_bad_output": 0,
            "fallback_used": 0,
            "fallback_failures": 0,
            "none_used": 0,
            "max_core_s": 0.0,
            "first_core_traceback": _LOAD_ERRORS.get("core"),
            "core_loaded": _CORE_CLS is not None,
            "fallback_loaded": _FALLBACK_CLS is not None,
            "core_init_error": None,
            "fallback_init_error": None,
            "fallback_load_error": _LOAD_ERRORS.get("fallback"),
            "first_fallback_error": None,
        }
        try:
            if _CORE_CLS is not None:
                lim = _CORE_INIT_LIMIT_S
                status, value, error, secs = _call(_CORE_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._core = value
                else:
                    msg = _describe(status, error, secs, lim)
                    self._stats["core_init_error"] = msg
                    if self._stats["first_core_traceback"] is None:
                        self._stats["first_core_traceback"] = msg
            if _FALLBACK_CLS is not None:
                lim = _FALLBACK_INIT_LIMIT_S
                status, value, error, secs = _call(_FALLBACK_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._fallback = value
                else:
                    self._stats["fallback_init_error"] = _describe(status, error, secs, lim)
        except BaseException:
            pass

    def act(self, obs):
        try:
            return self._act(obs)
        except BaseException:
            return None

    def _act(self, obs):
        t0 = _time.perf_counter()
        st = self._stats
        st["turns"] += 1
        core, fallback = self._core, self._fallback
        saved = None
        if core is not None:
            if fallback is not None:
                try:
                    saved = repr(obs)  # the core may mutate obs; the fallback gets a fresh copy
                except Exception:
                    saved = None
            limit = _ACT_LIMIT_S * _CORE_SHARE
            status, value, error, secs = _call(_act_of, (core, obs), limit, True)
            if secs > st["max_core_s"]:
                st["max_core_s"] = secs
            if status == "ok":
                st["core_ok"] += 1
                return value
            if status == "timeout":
                st["core_timeouts"] += 1
            elif status == "bad":
                st["core_bad_output"] += 1
            else:
                st["core_exceptions"] += 1
            if st["first_core_traceback"] is None:
                st["first_core_traceback"] = _describe(status, error, secs, limit)
            error = None
        if fallback is not None:
            fobs = obs
            if saved is not None:
                try:
                    fobs = _ast.literal_eval(saved)
                except Exception:
                    fobs = obs
            left = _ACT_LIMIT_S - (_time.perf_counter() - t0)
            if left >= _MIN_FALLBACK_S:
                status, value, error, secs = _call(_act_of, (fallback, fobs), left, True)
                if status == "ok":
                    st["fallback_used"] += 1
                    return value
                st["fallback_failures"] += 1
                if st["first_fallback_error"] is None:
                    st["first_fallback_error"] = _describe(status, error, secs, left)
        st["none_used"] += 1
        return None

    def guard_stats(self):
        """Counters of this instance: how often the core answered, failed, fell back."""
        try:
            return dict(self._stats)
        except BaseException:
            return {}


for _fn in (_call, _HzGuard.__init__, _HzGuard.act, _HzGuard._act, _HzGuard.guard_stats):
    _GUARD_CODES.add(_fn.__code__)
del _fn


class Strategy(_HzGuard):
    """Guarded strategy: never raises, never exceeds its time limit."""
